import{_ as a,o as d,c as e,ai as r}from"./chunks/framework.ampVZV4B.js";const m=JSON.parse('{"title":"Java · 05 常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/java/05-faq.md","filePath":"tech-system/backend/java/05-faq.md"}'),h={name:"tech-system/backend/java/05-faq.md"};function i(l,t,o,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="java-·-05-常见问题" tabindex="-1">Java · 05 常见问题 <a class="header-anchor" href="#java-·-05-常见问题" aria-label="Permalink to “Java · 05 常见问题”">​</a></h1><blockquote><p>排障入口。跨语言共性另见 <a href="./../problems/">后端问题</a>；面试细题见 <a href="/my-vitepress-site/guide/">就业指南</a>。</p></blockquote><h2 id="_1-语言-jvm" tabindex="-1">1. 语言 / JVM <a class="header-anchor" href="#_1-语言-jvm" aria-label="Permalink to “1. 语言 / JVM”">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>怎么看</th><th>怎么动</th></tr></thead><tbody><tr><td>OOM / 堆飙高</td><td>泄漏或缓存无界居多</td><td>dump、看占支配类、查本地/Redis 缓存上限</td></tr><tr><td>频繁 Full GC</td><td>分配过快或存活集太大</td><td>先减分配与缓存，再谈调参</td></tr><tr><td>CPU 飙高</td><td>死循环、锁竞争、正则/序列化</td><td>采样线程栈，对准热点方法</td></tr><tr><td>启动很慢</td><td>扫描面过大、依赖重、磁盘慢</td><td>启动报告、精简自动配置</td></tr><tr><td>元空间 OOM</td><td>动态类/代理过多或泄漏</td><td>查热部署、脚本引擎、反射生成</td></tr></tbody></table><p>原则：<strong>没有证据不调 GC 参数当第一反应。</strong></p><hr><h2 id="_2-并发与线程池" tabindex="-1">2. 并发与线程池 <a class="header-anchor" href="#_2-并发与线程池" aria-label="Permalink to “2. 并发与线程池”">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>常见原因</th></tr></thead><tbody><tr><td>接口偶发卡住</td><td>池队列满、死锁、锁内远程调用</td></tr><tr><td><code>OutOfMemoryError: unable to create new native thread</code></td><td>线程无界创建</td></tr><tr><td>数据偶发错乱</td><td>共享可变无同步；<code>HashMap</code> 并发写</td></tr><tr><td><code>volatile</code> 没用</td><td>误当成原子性工具</td></tr></tbody></table><p>处理：有界池 + 明确拒绝策略；共享状态最小化；复合操作要原子方案。</p><hr><h2 id="_3-spring-事务" tabindex="-1">3. Spring / 事务 <a class="header-anchor" href="#_3-spring-事务" aria-label="Permalink to “3. Spring / 事务”">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>常见原因</th><th>处理</th></tr></thead><tbody><tr><td><code>@Transactional</code> 不生效</td><td>同类自调用、非 public、异常被吃、没进 Spring 代理</td><td>注入自身/拆服务方法；抛出让回滚的异常</td></tr><tr><td>事务太大锁表</td><td>长事务含远程/大循环</td><td>缩短事务；先落状态再异步</td></tr><tr><td>循环依赖启动失败</td><td>构造器互环</td><td>拆模块、Setter/<code>ObjectProvider</code>、或 <code>@Lazy</code>（治标）</td></tr><tr><td>注入失败</td><td>多实现未 <code>@Qualifier</code>、包没被扫描</td><td>看启动日志 Bean 定义</td></tr><tr><td>配置没生效</td><td>profile 错、配置被覆盖、拼写错</td><td>启动打印有效配置（注意脱敏）</td></tr></tbody></table><p>事务口诀：<strong>代理、异常、边界</strong> 三件事先查。</p><hr><h2 id="_4-web-数据-缓存" tabindex="-1">4. Web / 数据 / 缓存 <a class="header-anchor" href="#_4-web-数据-缓存" aria-label="Permalink to “4. Web / 数据 / 缓存”">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>优先动作</th></tr></thead><tbody><tr><td>接口超时</td><td>看本服务池、DB 池、下游 RT、慢 SQL</td></tr><tr><td>慢 SQL</td><td>执行计划、索引、是否 select *、是否 N+1</td></tr><tr><td>更新丢失</td><td>并发写无版本号/乐观锁；事务隔离误解</td></tr><tr><td>缓存与 DB 不一致</td><td>先定「谁为准」与失效策略，再谈锁</td></tr><tr><td>缓存击穿/穿透/雪崩</td><td>空值缓存、互斥重建、过期打散——按真实流量上</td></tr></tbody></table><p>开放接口再补：鉴权、幂等键、限流、签名校验。</p><hr><h2 id="_5-架构与选型" tabindex="-1">5. 架构与选型 <a class="header-anchor" href="#_5-架构与选型" aria-label="Permalink to “5. 架构与选型”">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>建议</th></tr></thead><tbody><tr><td>要不要上 Cloud？</td><td>发布独立性与团队规模不够 → 先模块化单体</td></tr><tr><td>要不要上 MQ？</td><td>有削峰、异步解耦、最终一致再上；不为「简历有 MQ」</td></tr><tr><td>Java 还是 Python？</td><td>状态与业务权威在 Java；模型与脚本在 Python</td></tr><tr><td>要不要拆微服务？</td><td>默认否；痛点是独立演进/故障隔离时再拆</td></tr><tr><td>单体已经很乱</td><td>先划模块与表归属，再谈进程拆分</td></tr></tbody></table><hr><h2 id="_6-和项目相关的高频坑" tabindex="-1">6. 和项目相关的高频坑 <a class="header-anchor" href="#_6-和项目相关的高频坑" aria-label="Permalink to “6. 和项目相关的高频坑”">​</a></h2><h3 id="ai-异步任务" tabindex="-1">AI 异步任务 <a class="header-anchor" href="#ai-异步任务" aria-label="Permalink to “AI 异步任务”">​</a></h3><ul><li>只调通 Demo、没有任务表与状态 → 无法重试与对账</li><li>重试不幂等 → 重复扣费/重复生成</li><li>模型错误与网络错误不分类 → 乱重试打爆额度</li></ul><h3 id="mes-多端" tabindex="-1">MES / 多端 <a class="header-anchor" href="#mes-多端" aria-label="Permalink to “MES / 多端”">​</a></h3><ul><li>设备时钟与服务器时钟不一致 → 追溯对不上</li><li>采集风暴打满连接池 → 业务接口一起挂；要隔离与限流</li></ul><h3 id="crm-定制" tabindex="-1">CRM 定制 <a class="header-anchor" href="#crm-定制" aria-label="Permalink to “CRM 定制”">​</a></h3><ul><li>客户化直接改公共核心 → 升级即冲突；能配置化就配置化</li><li>大事务里调企业微信/钉钉 → 超时回滚惨案</li></ul><hr><h2 id="_7-相关入口" tabindex="-1">7. 相关入口 <a class="header-anchor" href="#_7-相关入口" aria-label="Permalink to “7. 相关入口”">​</a></h2><ul><li><a href="./01-basics.html">01 语言基础</a> · <a href="./02-core.html">02 核心能力</a> · <a href="./03-frameworks.html">03 框架</a> · <a href="./04-engineering.html">04 工程</a></li><li><a href="./../problems/">后端问题总览</a></li><li><a href="/my-vitepress-site/framework/overview.html">就业指南 · 框架</a> · <a href="/my-vitepress-site/database/overview.html">数据库</a> · <a href="/my-vitepress-site/redis/overview.html">Redis</a></li></ul>',31)])])}const f=a(h,[["render",i]]);export{m as __pageData,f as default};
